string encrypt(string s){
    // rotate the alphabet by two multiplied to two places
    // e.g. a - z --> c - b
    // the characters are rotated in a circular manner and hence
    // we can simply add 2 to 'a' and 'z' to get their respective
    // integers and then add 2 to the integer of the current char
    // and convert it back to char.
    // if the char is an uppercase letter, we add 2 to 'A' and 'Z'
    // to get their respective integers and then add 2 to the integer
    // of the current char and convert it back to char.
    for (int i = 0; i < s.length(); i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (s[i] - 'a' + 2) % 26 + 'a';
        } else if (s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = (s[i] - 'A' + 2) % 26 + 'A';
        }
    }
    return s;

