vector<float> rescale_to_unit(vector<float> numbers){ 
    assert(numbers.size() >= 2);
  // mean
  float sum = std::accumulate(numbers.begin(), numbers.end(), 0.0);
  float mean = sum / numbers.size();
  // std
  std::vector<float> diff(numbers.size());
  std::transform(numbers.begin(), numbers.end(), diff.begin(),
                 std::bind2nd(std::minus<float>(), mean));
  float sq_sum = std::inner_product(diff.begin(), diff.end(), diff.begin(), 0.0);
  float stdev = std::sqrt(sq_sum / numbers.size());
  // rescale
  for (int i = 0; i < numbers.size(); i++) {
    numbers[i] = (numbers[i] - mean) / stdev;
  }
  return numbers;

