        int digit = number / numbers[i];
        if (digit != 0) {
            if (digit == 9)
                return letters[i] + letters[i + 1];
            else if (digit >= 5)
                return letters[i] + std::string(digit - 5, letters[i][0]);
            else if (digit == 4)
                return letters[i] + letters[i];
            else
                return std::string(digit, letters[i][0]);
        }
        number %= numbers[i];
    }
    return "";

