    std::deque<long> dq;
    // Traverse the list of numbers and add the element to the queue
    for (auto num : numbers) {
        // if the queue is empty or the last element of the queue is
        // less than the current number, push the current number in
        // the queue.
        if (dq.empty() || dq.back() < num) {
            dq.push_back(num);
        } else {
            // else if the last element of the queue is greater than
            // the current number, pop elements from the back until the
            // current number is the last element of the queue.
            while (!dq.empty() && dq.back() > num) {
                dq.pop_back();
            }
            // Add the current number to the queue.
            dq.push_back(num);
        }
        // store the first element of the queue.
        result.push_back(dq.front());
    }
    return result;

