        // firstly, remove old elements from the queue
        while (!aux.empty() && aux.front() <= i - numbers.size()) {
            aux.pop_front();
        }
        // now, we keep only elements which are bigger or equal than numbers[i]
        while (!aux.empty() && numbers[aux.back()] <= numbers[i]) {
            aux.pop_back();
        }
