    // And a stack with at least one element, because we will be using peek() method of it:
    std::stack<long> s;
    s.push(numbers[0]);
    // Iterate over the given list starting from the second element:
    for (int i = 1; i < numbers.size(); i++) {
        // While stack has elements, and the last one is <= than the one we are considering right now,
        // pop them out of the stack:
        while (!s.empty() && s.top() <= numbers[i]) {
            s.pop();
        }
        // After the loop above, stack is empty or the last element from it is > than the one we are
        // considering right now. No matter which, we need to add the last element from the stack to the
        // output list:
        output_list[i] = s.top();
        // Now add the current number to the stack:
        s.push(numbers[i]);
    }
    return output_list;

