#include<math.h>
#include<vector>
using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<int> count_up_to(int n){
    std::vector<long> primes;
    if (n <= 1) {
        return primes;
    }
    std::vector<bool> notPrime(n + 1, false);
    //for a number i, if the number is not Prime, i*i will not be Prime either
    //e.g. if 4 is not prime, neither 8,12,16...will be. So we only need to test upto sqrt(n)
    for (long i = 2; i <= std::sqrt(n); i++) {
        //if i is Prime
        if (!notPrime[i]) {
            for (long j = i * i; j <= n; j += i) {
                notPrime[j] = true;
            }
        }
    }
    for (long i = 2; i <= n; i++) {
        if (!notPrime[i]) {
            primes.push_back(i);
        }
    }
    return primes;

