#include<math.h>
#include<vector>
using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<int> count_up_to(int n){
    std::vector<long> result;
    std::vector<bool> is_prime;
    is_prime.resize(n + 1, true);
    is_prime[0] = false;
    is_prime[1] = false;
    long next_prime = 2;
    while (next_prime <= n) {
        result.push_back(next_prime);
        // When finding the next prime, we can start from next_prime * next_prime because:
        // 1. if we have a k * next_prime, where k < next_prime, this value would have been set
        // when k is the next_prime;
        // 2. next_prime * next_prime is the smallest value that is multiple of next_prime that
        // hasn't been visited
        for (long i = next_prime * next_prime; i <= n; i += next_prime) {
            is_prime[i] = false;
        }
        // The next prime must be the smallest number that is prime and greater than next_prime.
        for (long i = next_prime + 1; i <= n; i++) {
            if (is_prime[i]) {
                next_prime = i;
                break;
            }
        }
    }
    return result;

