#include<vector>
#include<string>
using namespace std;
#include<algorithm>
#include<math.h>
#include<stdlib.h>
vector<int> parse_nested_parens(string paren_string){
    std::vector<long> result;
  std::string token;
  std::istringstream tokenStream(paren_string);
  while (std::getline(tokenStream, token, ' ')) {
    std::stack<char> parens;
    long deepest = 0;
    for (char c : token) {
      if (c == '(') {
        parens.push(c);
        deepest = std::max(deepest, (long)parens.size());
      } else if (c == ')') {
        if (parens.empty()) {
          throw std::invalid_argument("Unbalanced parentheses");
        }
        parens.pop();
      }
    }
    if (!parens.empty()) {
      throw std::invalid_argument("Unbalanced parentheses");
    }
    result.push_back(deepest);
  }
  return result;

